"""Real-browser smoke test. MODE=file runs it against file:// pages (no server). Needs: pip install playwright; python3 -m http.server 8123 running in the project root.
Usage: python3 tests/e2e_smoke.py [chromium-path]"""
import sys, asyncio, pathlib
from playwright.async_api import async_playwright
import os
ROOT = pathlib.Path(__file__).resolve().parents[1]
BASE = ('file://' + str(ROOT / 'pages') + '/') if os.environ.get('MODE') == 'file' else 'http://localhost:8123/pages/'
PAGES = ['dashboard','pos','products','categories','inventory','purchases','suppliers','customers','expenses','sales','reports','cash','users','settings']
fails = []
def check(name, cond):
    print(('PASS ' if cond else 'FAIL ') + name); cond or fails.append(name)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=sys.argv[1] if len(sys.argv) > 1 else None, args=['--no-sandbox'])
        ctx = await b.new_context(viewport={'width': 1280, 'height': 900}); pg = await ctx.new_page(); errs = []
        pg.on('pageerror', lambda e: errs.append(str(e))); pg.on('console', lambda m: errs.append(m.text) if m.type == 'error' else None)
        await pg.goto(BASE + 'login.html'); await pg.fill('#n', 'Boss'); await pg.fill('#p1', '1234'); await pg.fill('#p2', '1234'); await pg.click('#go'); await pg.wait_for_url('**/dashboard.html')
        check('first-run admin created and signed in', True)
        for n in PAGES:
            await pg.goto(BASE + n + '.html'); await pg.wait_for_selector('#view')
            await pg.wait_for_function("!document.querySelector('#view .loading')")
            check(f'page {n} renders shell ({await pg.locator("nav a").count()} nav links)', await pg.locator('nav a').count() == 14)
        await pg.goto(BASE + 'dashboard.html'); await pg.wait_for_selector('.kpi')
        check('dashboard KPIs + demo banner', await pg.locator('.kpi').count() == 4 and 'Demo data' in await pg.inner_text('#view'))
        await pg.goto(BASE + 'products.html'); await pg.click('#add')
        for k, v in [('name', 'Test Item'), ('sku', 'T1'), ('barcode', '999'), ('price', '100'), ('cost', '80'), ('stock', '5')]: await pg.fill('#f_' + k, v)
        await pg.click('[data-a=save]'); await pg.wait_for_selector('td:has-text("Test Item")'); check('product created', True)
        await pg.goto(BASE + 'pos.html'); await pg.fill('#q', '999'); await pg.press('#q', 'Enter')
        check('barcode scan adds to cart', 'Test Item' in await pg.inner_text('#cart'))
        await pg.reload(); await pg.wait_for_selector('#cart .cl'); check('cart restored after refresh', 'Test Item' in await pg.inner_text('#cart'))
        await pg.click('[data-a=pay]'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('.receipt')
        check('receipt shown with reference', 'S-' in await pg.inner_text('.receipt'))
        await pg.click('dialog [data-a=x]'); await pg.goto(BASE + 'products.html'); await pg.wait_for_selector('td:has-text("Test Item")')
        row = await pg.locator('tr:has-text("Test Item")').inner_text(); check('stock reduced 5 -> 4 after sale', '\t4' in row or ' 4' in row)
        await pg.goto(BASE + 'inventory.html'); await pg.click('tr:has-text("Test Item") button')
        await pg.select_option('#t', 'damaged'); await pg.fill('#q', '1'); await pg.fill('#n', 'dropped'); await pg.click('dialog [data-a=ok]')
        await pg.wait_for_selector('td:has-text("Damaged")'); check('damaged stock logged in movements', True)
        await pg.goto(BASE + 'expenses.html'); await pg.fill('#a', '250'); await pg.fill('#n', 'test'); await pg.click('#save'); await pg.wait_for_selector('td:has-text("KSh 250.00")'); check('expense saved', True)
        await pg.goto(BASE + 'sales.html'); await pg.wait_for_selector('td:has-text("S-")'); check('sale in history', True)
        await pg.goto(BASE + 'suppliers.html'); await pg.click('#add'); await pg.fill('#f_name', 'Mumias Distributors'); await pg.click('[data-a=save]'); await pg.wait_for_selector('td:has-text("Mumias Distributors")'); check('supplier created', True)
        await pg.goto(BASE + 'purchases.html'); await pg.click('#new'); await pg.fill('#inv', 'INV-77')
        await pg.select_option('[data-p]', label='Test Item'); await pg.fill('[data-q]', '10'); await pg.fill('[data-c]', '90'); await pg.click('[data-a=recv]')
        await pg.wait_for_selector('td:has-text("received")'); check('purchase saved and received', True)
        await pg.goto(BASE + 'inventory.html'); await pg.wait_for_selector('td:has-text("Stock received")'); check('receipt logged in stock movements', True)
        await pg.goto(BASE + 'suppliers.html'); await pg.wait_for_selector('td:has-text("KSh 900.00")'); check('supplier balance owed = KSh 900', True)
        await pg.goto(BASE + 'customers.html'); await pg.click('#add'); await pg.fill('#f_name', 'Wanjiku'); await pg.fill('#f_creditLimit', '500'); await pg.click('[data-a=save]'); await pg.wait_for_selector('td:has-text("Wanjiku")')
        await pg.goto(BASE + 'pos.html'); await pg.select_option('select[data-a=cust]', label='Wanjiku'); await pg.fill('#q', '999'); await pg.press('#q', 'Enter')
        await pg.click('[data-a=pay]'); await pg.select_option('[data-m="0"]', 'credit'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('.receipt')
        check('credit sale receipt names customer', 'Wanjiku' in await pg.inner_text('.receipt')); await pg.click('dialog [data-a=x]')
        await pg.goto(BASE + 'customers.html'); await pg.wait_for_selector('td:has-text("KSh 100.00")'); check('customer credit owed = KSh 100 and 1 point', '1' in await pg.inner_text('tr:has-text("Wanjiku")'))
        await pg.click('tr:has-text("Wanjiku") [data-a=pay]'); await pg.fill('#p_amt', '100'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('.toast:has-text("Payment recorded")'); check('credit repayment recorded', True)
        await pg.goto(BASE + 'sales.html'); await pg.wait_for_selector('[data-a=ret]'); await pg.locator('[data-a=ret]').first.click()
        await pg.fill('[data-rq]', '1'); await pg.select_option('#rm', 'cash'); await pg.fill('#why', 'wrong item'); await pg.click('dialog [data-a=ok]')
        await pg.wait_for_selector('#aud td:has-text("wrong item")'); check('return processed and audited', True)
        check('sale marked returned', 'returned' in await pg.inner_text('#tbl'))
        await pg.goto(BASE + 'inventory.html'); await pg.wait_for_selector('td:has-text("return")'); check('return restocked and logged', True)
        await pg.goto(BASE + 'reports.html'); await pg.wait_for_selector('.kpi'); await pg.select_option('#k', 'month'); await pg.wait_for_selector('h2:has-text("Best-selling")')
        check('reports render for the month', await pg.locator('.kpi').count() == 4)
        await pg.select_option('#k', 'custom'); check('custom date range shown', await pg.locator('#from').is_visible())
        await pg.goto(BASE + 'cash.html'); await pg.fill('#fl', '500'); await pg.click('[data-a=open]'); await pg.wait_for_selector('h2:has-text("Open shift")')
        await pg.click('[data-a=in]'); await pg.fill('#am', '200'); await pg.fill('#why', 'float top-up'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("KSh 700.00")'); check('shift expected cash = float + cash in = KSh 700', True)
        await pg.click('[data-a=close]'); await pg.fill('#ct', '690'); check('shortage shown before closing', 'Short by KSh 10.00' in await pg.inner_text('#df')); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("Short KSh 10.00")'); check('shift closed with variance recorded', True)
        await pg.goto(BASE + 'categories.html'); await pg.wait_for_selector('td:has-text("Beverages")'); check('categories imported from products', True)
        await pg.click('tr:has-text("Beverages") [data-a=sub]'); await pg.fill('#n', 'Sodas'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("Sodas")')
        await pg.click('tr:has-text("Sodas") [data-a=del]'); await pg.click('dialog [data-v="1"]'); await pg.wait_for_selector('td:has-text("Sodas")', state='detached'); check('subcategory added and deleted', True)
        await pg.click('tr:has-text("Beverages") [data-a=ren]'); await pg.fill('#n', 'Drinks'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("Drinks")')
        await pg.goto(BASE + 'pos.html'); await pg.wait_for_selector('.chip:has-text("Drinks")'); await pg.click('.chip:has-text("Drinks")'); check('POS category filter uses renamed category', await pg.locator('.pbtn').count() == 2)
        await pg.goto(BASE + 'users.html'); await pg.click('#add'); await pg.fill('#n', 'Achieng'); await pg.select_option('#r', 'cashier'); await pg.fill('#p', '4321'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("Achieng")')
        await pg.click('#logout'); await pg.wait_for_selector('#u'); await pg.select_option('#u', label='Achieng (cashier)'); await pg.fill('#p1', '0000'); await pg.click('#go'); check('wrong PIN rejected', 'Wrong PIN' in await pg.inner_text('#err'))
        await pg.fill('#p1', '4321'); await pg.click('#go'); await pg.wait_for_url('**/pos.html'); await pg.wait_for_selector('#cart')
        check('cashier sees only 6 menu items', await pg.locator('nav a').count() == 6); check('cashier cannot apply discounts', await pg.locator('select[data-a=dtype]').is_disabled())
        await pg.goto(BASE + 'reports.html'); await pg.wait_for_selector('.empty'); check('cashier blocked from reports', 'Access denied' in await pg.inner_text('#view'))
        await pg.goto(BASE + 'sales.html'); await pg.wait_for_selector('[data-a=rcpt]'); check('cashier has no return/cancel buttons', await pg.locator('[data-a=ret], [data-a=void]').count() == 0)
        await pg.click('#logout'); await pg.wait_for_selector('#u'); await pg.select_option('#u', label='Boss (admin)'); await pg.fill('#p1', '1234'); await pg.click('#go'); await pg.wait_for_url('**/dashboard.html'); check('admin signs back in', True)
        open('/tmp/imp.csv', 'w').write('name,sku,unit,category,price,cost,stock\nImport A,IA1,piece,Snacks,50,40,12\nBad One,IB1,piece,Snacks,-5,40,1\n')
        await pg.goto(BASE + 'products.html'); await pg.wait_for_selector('#imp'); await pg.set_input_files('#impf', '/tmp/imp.csv'); await pg.wait_for_selector('dialog')
        check('import previews 1 ready and 1 problem', '1 ready to import, 1 with problems' in await pg.inner_text('dialog')); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("Import A")'); check('CSV import added product', True)
        await pg.goto(BASE + 'expenses.html'); await pg.wait_for_selector('[data-a=edit]'); await pg.locator('[data-a=edit]').first.click(); await pg.fill('#e_a', '300'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('td:has-text("KSh 300.00")'); check('expense edited', True)
        await pg.locator('[data-a=void]').first.click(); await pg.fill('#why', 'duplicate'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('span.tag:has-text("voided")'); await pg.wait_for_selector('#log td:has-text("duplicate")'); check('expense voided and logged', True)
        await pg.goto(BASE + 'purchases.html'); await pg.click('#new'); await pg.fill('#inv', 'INV-EDIT'); await pg.select_option('[data-p]', label='Test Item'); await pg.fill('[data-q]', '5'); await pg.fill('[data-c]', '90'); await pg.click('dialog [data-a=order]'); await pg.wait_for_selector('td:has-text("INV-EDIT")')
        await pg.click('tr:has-text("INV-EDIT") [data-a=edit]'); await pg.fill('[data-q]', '7'); await pg.click('dialog [data-a=order]'); await pg.wait_for_selector('tr:has-text("INV-EDIT"):has-text("KSh 630.00")'); check('purchase order edited (7 x 90 = 630)', True)
        await pg.click('tr:has-text("INV-EDIT") [data-a=cancel]'); await pg.fill('#why', 'supplier out of stock'); await pg.click('dialog [data-a=ok]'); await pg.wait_for_selector('tr:has-text("INV-EDIT") span:has-text("cancelled")'); check('purchase order cancelled', True)
        await pg.goto(BASE + 'settings.html'); await pg.fill('#tax', '16'); await pg.click('#save'); await pg.wait_for_selector('.toast')
        await pg.goto(BASE + 'pos.html'); await pg.fill('#q', '999'); await pg.press('#q', 'Enter'); check('tax line on POS after settings', 'Tax 16%' in await pg.inner_text('#cart'))
        await pg.goto(BASE + 'settings.html'); await pg.wait_for_selector('#bk')
        async with pg.expect_download() as dl: await pg.click('#bk')
        await (await dl.value).save_as('/tmp/bk.json')
        await pg.goto(BASE + 'suppliers.html'); await pg.click('#add'); await pg.fill('#f_name', 'Temp Supplier'); await pg.click('dialog [data-a=save]'); await pg.wait_for_selector('td:has-text("Temp Supplier")')
        await pg.goto(BASE + 'settings.html'); await pg.set_input_files('#rf', '/tmp/bk.json'); await pg.click('dialog [data-v="1"]'); await pg.wait_for_timeout(1800)
        await pg.goto(BASE + 'suppliers.html'); await pg.wait_for_selector('td:has-text("Mumias")'); check('restore brought back the backed-up state', 'Temp Supplier' not in await pg.inner_text('#tbl'))
        for w in (390, 768):
            await pg.set_viewport_size({'width': w, 'height': 800})
            for n in PAGES + ['login']:
                await pg.goto(BASE + n + '.html'); await pg.wait_for_selector('#app > *'); await pg.wait_for_function("!document.querySelector('#view .loading')") if n != 'login' else None
                over = await pg.evaluate('document.documentElement.scrollWidth - window.innerWidth'); check(f'no sideways scroll: {n} at {w}px', over <= 1)
        check('no console/page errors', not errs); print(errs[:5])
        await b.close()
    print('\nFAILED:' if fails else '\nALL PASSED', fails or '')
    sys.exit(1 if fails else 0)
asyncio.run(main())
